// ============================================================ ROMA: el resto de Italia, Sicilia y las provincias (año 80 d.C.)
function r3Sea(I,label){if(I.coast)seaPort(I,label,I.coast[0],I.coast[1]);}
function r3Camp(x,z,w,d,name,leg){const gy=minGround(x,z,w,d,0),wm=lam(leg==='wood'?'#7a5a3a':'#a89c80'),g=grp(x,gy,z,0);
  for(const[s,ax]of[[-1,'z'],[1,'z'],[-1,'x'],[1,'x']]){const L=ax==='z'?w:d;for(const half of[-1,1]){const len=L/2-6,c=half*(6+len/2);if(ax==='z')box(len,4,1.2,wm,c,2,s*d/2,g);else box(1.2,4,len,wm,s*w/2,2,c,g);}
   for(const half of[-1,1]){const tx=ax==='z'?half*6:s*w/2,tz=ax==='z'?s*d/2:half*6;box(3,7,3,wm,tx,3.5,tz,g);}}
  for(const[cx,cz]of[[-w/2,-d/2],[w/2,-d/2],[-w/2,d/2],[w/2,d/2]])box(3.5,6,3.5,wm,cx,3,cz,g);
  for(let i=0;i<Math.floor(w/16);i++)for(const s of[-1,1]){const bx=-w/2+12+i*16;if(Math.abs(bx)<8)continue;box(10,3,30,lam(leg==='wood'?'#8a6a48':'#d8cdb2'),bx,1.5,s*(d/4+4),g);}
  box(18,5,14,lam('#e8dfcc'),0,2.5,0,g);addBox(x,z,18,14,0);
  for(const[a,b,c,e]of[[-w/2,-d/2,-6,-d/2],[6,-d/2,w/2,-d/2],[-w/2,d/2,-6,d/2],[6,d/2,w/2,d/2],[-w/2,-d/2,-w/2,-6],[-w/2,6,-w/2,d/2],[w/2,-d/2,w/2,-6],[w/2,6,w/2,d/2]])addSeg(x+a,z+b,x+c,z+e,0.7);
  footprints.push({x,z,w,d,a:0,c:'#b8ab88',name});return g;}
function r3Ruins(x,z,n,sp,col){const m=lam(col||'#cdbf9f');for(let i=0;i<n;i++){const px=x+rr(-sp,sp),pz=z+rr(-sp,sp),y=terrainH(px,pz);if(R()<0.5){const h=rr(0.4,2.2);const b=box(rr(3,8),h,0.8,m,px,y+h/2-0.2,pz);b.rotation.y=R()<0.5?0:Math.PI/2;}else{const c=new THREE.Mesh(new THREE.CylinderGeometry(0.45,0.5,rr(0.6,4),12),m);c.position.set(px,y+c.geometry.parameters.height/2,pz);c.castShadow=true;scene.add(c);}}}
function r3Lighthouse(x,z,h){const y=terrainH(x,z),g=grp(x,y,z,0),m=lam('#e8dfcc');box(10,h*0.5,10,m,0,h*0.25,0,g);box(7,h*0.3,7,m,0,h*0.65,0,g);const c=new THREE.Mesh(new THREE.CylinderGeometry(2.4,2.8,h*0.2,10),m);c.position.y=h*0.9;g.add(c);
  const f=new THREE.Mesh(new THREE.SphereGeometry(1.4,10,8),new THREE.MeshBasicMaterial({color:0xffb050}));f.position.y=h+0.8;g.add(f);addBox(x,z,10,10,0);return g;}
function r3Cone(x,z,r,h,col,smoke){const y=terrainH(x,z);const c=new THREE.Mesh(new THREE.ConeGeometry(r,h,24,1,true),lam(col||'#5a524a'));c.position.set(x,y+h/2-4,z);scene.add(c);if(smoke)isl3Smoke(x,y+h,z,10,40);return c;}
function r3Tower(x,z,w,h,col){const y=terrainH(x,z),g=grp(x,y,z,0);box(w,h,w,lam(col||'#cdbf9f'),0,h/2,0,g);for(let k=-1;k<=1;k++)box(w/4,1.2,w/4,lam(col||'#cdbf9f'),k*w/3,h+0.6,w/2-w/8,g);addBox(x,z,w,w,0);return g;}
function r3Terraces(x,z,n,w,step,rise,col){const m=lam(col||'#d8cdb2');const y0=terrainH(x,z);for(let k=0;k<n;k++){const zz=z-k*step;box(w-k*6,rise*(k+1),step,m,x,y0+rise*(k+1)/2-0.5,zz);addBox(x,zz,w-k*6,step,0);}return y0+rise*n;}
function r3Plaque(x,z,id,name,gr,txt){const f=findFree(x,z,1.5)||[x,z];place(id,name,gr,txt,f[0],f[1],0);footprints.push({x:f[0],z:f[1],r:3});}
Object.assign(SIMPLE_RO,{
 // ---------------- Italia
 ostia:{npc:'mensor',label:'Ostia',roman:true,blobs:[],tx:20,tz:20,tr:110,site:[40,-60,20],houses:50,spread:140,rtemple:{name:'Templo de Vulcano (Ostia)'},
  steles:[['ostia_puerto','La boca del Tíber','OSTIA','Ostia es el puerto de Roma, en la boca del Tíber. Aquí se descargan el trigo, el aceite y el vino que alimentan la ciudad, y se suben río arriba en barcazas tiradas por bueyes. Como la desembocadura se llena de arena, Claudio construyó un gran puerto nuevo al norte, con un faro levantado sobre el barco enorme que había traído de Egipto el obelisco del Vaticano: lo hundieron lleno de piedra y lo usaron de cimiento.'],
   ['ostia_horrea','Los almacenes','HORREA','Las calles están llenas de almacenes de grano, los horrea, con patios y habitaciones frescas y suelos levantados para que no se moje el trigo. De aquí sale el trigo del reparto gratuito: unos doscientos mil ciudadanos de Roma lo reciben cada mes.']],
  extra(I){r3Sea(I,'Ostia');theatre({x:I.x+90,z:I.z+40,R0:8,R1:30,H:12,rot:Math.PI,name:'Teatro de Ostia (de Agripa)',noPlays:true});
   for(let k=0;k<6;k++){const x=I.x-60+k*26,z=I.z+130,gy=minGround(x,z,20,30,0),g=grp(x,gy,z,0);box(20,7,30,lam('#b5764a'),0,3.5,0,g);box(8,4,10,lam('#2a2018'),0,2,0,g);addBox(x,z,20,30,0);}
   /* el faro de Claudio, ahora en su isla del puerto (283_ostia_portus.js) */r3Plaque(I.x+60,I.z+120,'ostia_corporaciones','La plaza de las corporaciones','FORVM VINARIVM','Detrás del teatro, bajo un pórtico, tienen sus oficinas los navieros y comerciantes de cada puerto: los de Cartago, los de Narbona, los de Alejandría… Anacronismo señalado: los famosos mosaicos con el nombre de cada ciudad que se ven hoy son de un siglo después.');}},
 tibur:{npc:'lapicida',label:'Tibur',roman:true,blobs:[[200,-200,220,40],[-220,-260,200,35]],tx:-40,tz:20,tr:80,site:[60,-60,18],houses:30,spread:90,
  steles:[['tibur_sibila','El templo de la Sibila','TIBVRTINA','Sobre el precipicio del río Anio, donde el agua cae en cascadas entre la espuma, hay un templo redondo, de columnas corintias. Unos dicen que es de Vesta; otros, de la Sibila Tiburtina, una profetisa. Horacio dice que no hay lugar más bonito que Tibur y sus huertos regados por el agua que cae.'],
   ['tibur_travertino','La piedra de Tibur','LAPIS TIBVRTINVS','Cerca de Tibur se sacan bloques de travertino, una piedra blanca y porosa, dura y fácil de trabajar. Con ella se está terminando el gran anfiteatro de los Flavios en Roma: miles de carros bajan cada año por la Vía Tiburtina. Anacronismo señalado: la gran villa del emperador Adriano, que hoy se visita junto a Tívoli, se construirá unos cuarenta años después.']],
  extra(I){const s=I.site;roundTemple({x:s.x,z:s.z,r:7.2,colD:0.7,colH:8,n:18,pod:2,rot:0,name:'Templo redondo de Tibur'});
   const pts=[];for(let i=0;i<=30;i++){const t=i/30;pts.push([I.x+90+Math.sin(t*4)*20,I.z-I.R*1.1+t*I.R*1.8]);}addRiver(pts,10,{dep:2,name:'El Anio'});
   for(let k=0;k<4;k++){const x=I.x+200+k*12,z=I.z+120;box(10,rr(4,9),8,lam('#e8e2d0'),x,terrainH(x,z)+2,z);}}},
 praeneste:{npc:'sortilegus',label:'Praeneste',roman:true,blobs:[[0,-260,260,70]],tx:0,tz:120,tr:80,houses:30,spread:90,
  steles:[['fortuna_prim','El santuario de la Fortuna','FORTVNA PRIMIGENIA','En la ladera del monte se levanta, en terrazas gigantes, uno de los mayores santuarios de Italia: el de la Fortuna Primigenia, la primera hija de Júpiter. Arriba del todo, un templo redondo; abajo, rampas, pórticos y escaleras, como un teatro hecho para los dioses.'],
   ['sortes','Las suertes de Praeneste','SORTES','Cuenta Cicerón que un hombre de aquí soñó que debía partir una roca, y dentro encontró unas tablillas de roble con letras antiguas. Desde entonces, cuando alguien consulta a la diosa, un niño mezcla las tablillas en una caja de madera de olivo y saca una: lo que dice es la respuesta. Cicerón, que era escéptico, preguntaba por qué la Fortuna necesitaba a un niño.']],
  extra(I){const top=r3Terraces(I.x,I.z-60,6,90,14,4);const zt=I.z-60-6*14;roundTemple({x:I.x,z:zt-2,r:6,colD:0.6,colH:6,n:14,pod:1.5,gy:top,rot:0,name:'Templo de la Fortuna'});
   r3Plaque(I.x+40,I.z-40,'mosaico_nilo','El mosaico del Nilo','NILVS','En una sala del santuario hay un mosaico enorme con el Nilo en crecida: hipopótamos, cocodrilos, cazadores, templos y barcas, desde las montañas de Etiopía hasta el delta. Lo hicieron artistas de Alejandría hace casi dos siglos.');}},
 capua:{npc:'unguentarius',label:'Capua',roman:true,blobs:[[-300,-300,200,60]],tx:0,tz:20,tr:110,site:[-60,-80,22],houses:46,spread:130,rtemple:{name:'Templo de Capua'},
  steles:[['capua_lujo','La ciudad del lujo','CAPVA','Capua fue la ciudad más rica de Italia, tanto que dicen que sus delicias ablandaron al ejército de Aníbal en el invierno del 216 a.C.: los soldados que habían vencido en Cannas salieron de aquí más débiles. En la plaza Seplasia se venden los mejores perfumes del mundo.'],
   ['espartaco','Espartaco','SPARTACVS','En el 73 a.C., unos setenta gladiadores escaparon de la escuela de Léntulo Batiato, aquí en Capua, armados con cuchillos de cocina. Los dirigía un tracio, Espartaco. En dos años reunieron un ejército de esclavos de decenas de miles y vencieron a varios ejércitos romanos, hasta que Craso los derrotó. Seis mil fueron crucificados a lo largo de la Vía Apia, de Capua a Roma.']],
  extra(I){amphi(I.x+130,I.z-40,0,82,68,16,'Anfiteatro de Capua');forumR(I.x-10,I.z+20,40,26,'Foro de Capua');
   const s=I.x-150,t=I.z+120,g=grp(s,terrainH(s,t),t,0);box(30,4,22,lam('#d8cdb2'),0,2,0,g);addBox(s,t,30,22,0);r3Plaque(s+18,t,'ludus_capua','Una escuela de gladiadores','LVDVS','Capua tiene varias escuelas de gladiadores: patios rodeados de celdas, donde los hombres entrenan con armas de madera bajo la mirada de un maestro, el doctor.');}},
 cumae:{npc:'aedituus',label:'Cumas y Bayas',roman:true,blobs:[[-150,-200,120,50],[260,-260,180,30]],tx:150,tz:120,tr:90,site:[-150,-200,20,52],houses:24,spread:90,temple:{name:'Templo de Apolo (Cumas)',W:12,L:24},
  steles:[['sibila_cumas','La cueva de la Sibila','SIBYLLA','Virgilio cuenta que Eneas vino aquí a consultar a la Sibila de Cumas, la profetisa de Apolo, en una cueva enorme con cien bocas por las que salían cien voces. Ella lo guió a los Infiernos por el lago Averno, que está aquí al lado. Anacronismo señalado: la galería de piedra que hoy se visita como «antro de la Sibila» quizá fue otra cosa, quizá una obra militar.'],
   ['bayas','Bayas, la ciudad del placer','BAIAE','A pocos kilómetros, Bayas tiene las termas más famosas de Italia, con agua caliente que sale de la tierra, y las villas de los más ricos de Roma, construidas sobre el mar. Séneca la llamaba «la posada de los vicios»: fiestas en barca, borrachos en la playa, canciones toda la noche.']],
  extra(I){caveMouth(I.x-150,I.z-160,0);egxObj(I.x-150,I.z-155,undefined,'r3:sibila','La boca de la cueva','sale un aire frío',3);
   const L={x:I.x+60,z:I.z-60};const lk=new THREE.Mesh(new THREE.CircleGeometry(40,32),new THREE.MeshPhongMaterial({color:'#2a4a4a',shininess:60}));lk.rotation.x=-Math.PI/2;lk.position.set(L.x,terrainH(L.x,L.z)+0.3,L.z);scene.add(lk);
   r3Plaque(L.x-46,L.z,'averno','El lago Averno','AVERNVS','Un lago redondo y oscuro en un cráter. Su nombre griego, áornos, significa «sin pájaros»: decían que los gases mataban a los que lo sobrevolaban. Por aquí se bajaba a los Infiernos. Agripa lo unió al mar con un canal y lo convirtió en puerto de guerra.');
   for(let k=0;k<4;k++){const x=I.x+200+k*30,z=I.z+200,g=grp(x,terrainH(x,z),z,0);box(22,6,14,lam('#efe7d8'),0,3,0,g);const d=new THREE.Mesh(new THREE.SphereGeometry(5,12,6,0,TAU,0,Math.PI/2),lam('#d8cdb2'));d.position.y=6;g.add(d);addBox(x,z,22,14,0);}}},
 pompeii:{npc:'fossor',label:'Pompeya',roman:true,blobs:[[300,-260,330,190]],tx:-260,tz:200,tr:50,houses:8,spread:40,
  tint:(x,z,h,c)=>{c.lerp(_c2.set('#5e5a56'),0.9);},
  steles:[['pompeya_ceniza','Una ciudad bajo la ceniza','POMPEII','Hace menos de un año, el 24 de agosto (o quizá en otoño) del 79, el Vesubio despertó. Una columna de humo y piedras subió hasta el cielo y luego cayó sobre Pompeya, Herculano y Estabias. Bajo esta llanura gris, a seis metros de profundidad, hay una ciudad entera: casas, tiendas, templos y miles de personas. Solo asoman algunos tejados.'],
   ['plinio_viejo','Plinio el Viejo','PLINIVS','El almirante de la flota de Miseno, Plinio el Viejo, el autor de la Historia natural, cruzó la bahía con sus barcos para ayudar a los que huían y para ver la erupción de cerca. Murió en la playa de Estabias, ahogado por los gases. Anacronismo señalado: las cartas en las que su sobrino, Plinio el Joven, lo contó todo a Tácito se escribirán unos veinticinco años después.'],
   ['tito_pompeya','La ayuda del emperador','TITVS','El emperador Tito nombró a dos senadores para ayudar a los supervivientes, y dio para ello los bienes de los muertos que no tenían herederos. Algunos vuelven a cavar túneles en la ceniza para recuperar estatuas, mármol y lo que puedan de sus casas.']],
  extra(I){const cx=I.x+300,cz=I.z-260;let top=0;for(let dx=-50;dx<=50;dx+=10)for(let dz=-50;dz<=50;dz+=10)top=Math.max(top,terrainH(cx+dx,cz+dz));isl3Smoke(cx,top+8,cz,10,35);
   const rm=lam('#a8542e'),cm=lam('#d8cdb2');for(let i=0;i<40;i++){const x=I.x-120+rr(-110,110),z=I.z+rr(-120,120),y=terrainH(x,z);if(R()<0.6){const r=box(rr(5,10),0.6,rr(5,9),rm,x,y+0.2,z);r.rotation.set(0,R()*0.3,rr(-0.3,0.3));}else{const c=new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.4,rr(0.8,2.5),10),cm);c.position.set(x,y+0.6,z);scene.add(c);}}
   for(let k=0;k<3;k++){const x=I.x-80+k*40,z=I.z+60,y=terrainH(x,z);const p=new THREE.Mesh(new THREE.CylinderGeometry(1.2,1.2,0.3,12),lam('#1a1512'));p.position.set(x,y+0.05,z);scene.add(p);}
   egxObj(I.x-40,I.z+60,undefined,'r3:tunel','Un pozo en la ceniza','alguien ha cavado hasta un tejado',3);}},
 tarentum:{npc:'purpurarius',label:'Tarento',roman:true,blobs:[[-280,-250,200,30]],tx:-40,tz:-20,tr:100,site:[-80,-120,22],houses:40,spread:120,temple:{name:'Templo dórico de Tarento',W:14,L:30},
  steles:[['tarento_esparta','La colonia de Esparta','TARAS','Tarento la fundaron hace ocho siglos espartanos nacidos fuera del matrimonio, los partenios. Fue la ciudad griega más poderosa de Italia; aquí vivió Arquitas, filósofo, matemático y general, amigo de Platón. Cuando Roma la amenazó, llamó en su ayuda al rey Pirro del Epiro y sus elefantes. Perdió, y desde entonces es aliada de Roma.'],
   ['tarento_zeus','El Zeus de Lisipo','IVPPITER','En el ágora había un Zeus de bronce de Lisipo, de casi veinte metros. Cuando Fabio Máximo tomó la ciudad en el 209 a.C., se llevó a Roma el Hércules del mismo escultor, pero dejó el Zeus porque no podía moverlo. Dicen que se mueve con la mano, pero ningún viento lo derriba.']],
  extra(I){r3Sea(I,'Tarento');for(let k=0;k<8;k++){const x=I.x+150+rr(-30,30),z=I.z+100+rr(-20,20);const m=new THREE.Mesh(new THREE.ConeGeometry(rr(3,6),rr(2,4),10),lam('#c8bfb0'));m.position.set(x,terrainH(x,z)+1,z);scene.add(m);}
   egxObj(I.x+150,I.z+80,undefined,'r3:murex','Montones de conchas','de las que se saca la púrpura',6);}},
 aquileia:{npc:'sucinarius',label:'Aquilea',roman:true,blobs:[[-300,-300,200,20]],tx:0,tz:0,tr:110,site:[-60,-80,22],houses:46,spread:130,rtemple:{name:'Templo de Aquilea'},
  steles:[['aquilea_colonia','La puerta del nordeste','AQVILEIA','Aquilea se fundó en el 181 a.C. como colonia militar contra los pueblos de los Alpes. Hoy es una de las ciudades más ricas de Italia: por su puerto fluvial pasan el vino y el aceite hacia el Danubio, y bajan el hierro de Nórico, los esclavos, las pieles y el ámbar del norte.'],
   ['ambar','La ruta del ámbar','SVCINVM','Por una larga ruta que cruza el Danubio llega aquí el ámbar del mar del norte, la resina fósil que los romanos pagan a precio de oro. Plinio cuenta que Nerón mandó a un caballero hasta las costas del Báltico, y que volvió con tanto ámbar que adornó con él las redes del anfiteatro.']],
  extra(I){const pts=[];for(let i=0;i<=30;i++){const t=i/30;pts.push([I.x+180+Math.sin(t*3)*16,I.z-I.R*1.1+t*I.R*2]);}addRiver(pts,16,{dep:2.5,name:'El Natisón'});
   for(let k=0;k<5;k++){const x=I.x+150,z=I.z-100+k*30;box(14,0.8,6,lam('#8a6a48'),x,0.6,z);}forumR(I.x-10,I.z+10,46,28,'Foro de Aquilea');}},
 ravenna:{npc:'classiarius',label:'Rávena',roman:true,blobs:[],tx:-80,tz:20,tr:80,houses:30,spread:90,lake:[120,-60,140,110],
  steles:[['ravenna_flota','La flota del Adriático','CLASSIS RAVENNAS','Augusto instaló en Rávena una de las dos grandes flotas de guerra de Italia (la otra está en Miseno, junto a Neápolis). Desde aquí vigila el Adriático. El puerto, Classe, está en una laguna unida al mar por un canal.'],
   ['ravenna_agua','Una ciudad sobre el agua','RAVENNA','Rávena está en medio de lagunas y marismas: las casas se apoyan en pilotes de madera y se va de un barrio a otro en barca o por puentes. Marcial bromeaba con que aquí era más barata una cisterna que una viña: el agua dulce vale más que el vino.']],
  extra(I){r3Sea(I,'Rávena');const L=I.lake;for(let k=0;k<6;k++){const g=grp(L.x-60+k*22,0.3,L.z,0);box(3,1.4,18,lam('#6a4a2a'),0,0.7,0,g);for(let o=0;o<6;o++)box(0.15,0.1,2.6,lam('#5a3a1a'),(o%2?1:-1)*1.9,0.9,-6+o*2.4,g);}
   for(let k=0;k<30;k++){const x=I.x-150+rr(-60,60),z=I.z+80+rr(-40,40);const p=new THREE.Mesh(new THREE.CylinderGeometry(0.15,0.15,2,5),lam('#6a5038'));p.position.set(x,terrainH(x,z),z);scene.add(p);}}},
 mediolanum:{npc:'grammaticus',label:'Mediolanum',roman:true,blobs:[],tx:0,tz:0,tr:110,site:[-60,-70,22],houses:44,spread:120,rtemple:{name:'Templo de Mediolanum'},
  steles:[['mediolanum_celtas','La ciudad de los ínsubres','MEDIOLANVM','Mediolanum la fundaron los galos ínsubres, en medio de la llanura del Po: su nombre quiere decir, quizá, «en medio de la llanura». Roma la conquistó en el 222 a.C. Hoy es una ciudad próspera de la Transpadana, con buenas escuelas.'],
   ['virgilio_milan','El estudiante Virgilio','VERGILIVS','Cuenta su biografía antigua que Virgilio, el poeta de la Eneida, estudió aquí de joven, antes de irse a Roma y a Neápolis. Hoy los padres de la región mandan aquí a sus hijos a aprender gramática y retórica con buenos maestros.']],
  extra(I){forumR(I.x,I.z+20,44,28,'Foro de Mediolanum');theatre({x:I.x+150,z:I.z-60,R0:8,R1:34,H:13,rot:0,name:'Teatro de Mediolanum',noPlays:true});}},
 alpes:{npc:'mulio',label:'Augusta Praetoria',roman:true,blobs:[[-350,0,260,140],[350,0,260,150],[0,-430,300,170]],tx:0,tz:120,tr:80,houses:26,spread:70,
  tint:(x,z,h,c)=>{if(h>70)c.lerp(_c2.set('#8a8a86'),Math.min(0.8,(h-70)/40));if(h>110)c.lerp(_c2.set('#f4f6f6'),Math.min(1,(h-110)/20));},
  steles:[['salasos','La ciudad de los salasos','AVGVSTA PRAETORIA','En el 25 a.C. Augusto acabó con los salasos, el pueblo que controlaba este valle y cobraba peaje a todos los que cruzaban los Alpes. Según Estrabón, vendieron como esclavos a treinta y seis mil. En su lugar fundó esta colonia para tres mil veteranos de la guardia, con su cuadrícula perfecta de calles.'],
   ['alpis_graia','Los pasos de los Alpes','ALPIS GRAIA','Desde aquí salen dos caminos que cruzan los Alpes: uno hacia el Alpis Graia, hacia la Galia, y otro hacia el Alpis Poenina, hacia el país de los helvecios. En invierno la nieve los cierra. Los antiguos discuten por qué paso cruzó Aníbal con sus elefantes; nadie lo sabe con seguridad, todavía hoy.']],
  extra(I){const g=grp(I.x,terrainH(I.x,I.z+40),I.z+40,0),m=lam('#d8cdb2');box(12,12,6,m,-9,6,0,g);box(12,12,6,m,9,6,0,g);box(30,4,6,m,0,14,0,g);addBox(I.x-9,I.z+40,12,6,0);addBox(I.x+9,I.z+40,12,6,0);
   r3Plaque(I.x+18,I.z+50,'arco_augusto','El arco de Augusto','ARCVS','Un arco de piedra a la entrada de la colonia celebra la victoria de Augusto sobre los salasos.');}},
 // ---------------- Sicilia
 agrigentum:{npc:'periegetes',label:'Agrigento',roman:true,blobs:[[0,-260,300,40]],tx:0,tz:-220,tr:90,houses:30,spread:90,
  steles:[['agrigento_templos','La colina de los templos','AKRAGAS','Píndaro llamó a Agrigento «la más bella ciudad de los mortales». En el borde de una colina, frente al mar, sus habitantes levantaron una fila de templos dóricos de piedra dorada. Algunos siguen enteros; otros, caídos por terremotos y guerras. Anacronismo señalado: el más entero se llama hoy «de la Concordia» por una inscripción romana encontrada cerca, pero nadie sabe a qué dios estaba dedicado.'],
   ['olimpieion','El templo de los gigantes','OLYMPIEION','El templo de Zeus Olímpico iba a ser el mayor templo dórico del mundo griego. Entre sus columnas, gigantes de piedra de ocho metros sostenían el techo con los brazos. Nunca se terminó, y hoy es un campo de bloques caídos.'],
   ['falaris','El toro de Fálaris','PHALARIS','Fálaris, tirano de Agrigento, tenía un toro de bronce hueco: metía dentro a sus enemigos y encendía fuego debajo, y sus gritos salían por la boca como mugidos. Se cuenta que el primero en probarlo fue el escultor que lo inventó.']],
  extra(I){for(let k=0;k<4;k++){const x=I.x-180+k*120,z=I.z+60,f=k===1;temple({x,z,rot:0,W:16,L:38,nW:6,nL:13,colD:1.4,colH:6.8,name:f?'Templo «de la Concordia»':'Templo dórico de Agrigento',ruined:k===3});}
   r3Ruins(I.x+60,I.z+150,30,25,'#c9a870');for(let k=0;k<2;k++){const x=I.x+60+k*12,z=I.z+150,g=grp(x,terrainH(x,z),z,0.3);box(2.5,8,1.6,lam('#c9a870'),0,0.8,0,g).rotation.x=Math.PI/2;}}},
 segesta:{npc:'elymus',label:'Segesta',roman:true,blobs:[[-150,-200,200,45],[200,-260,180,40]],tx:-150,tz:-160,tr:60,houses:20,spread:60,
  steles:[['segesta_templo','Un templo sin terminar','SEGESTA','Este templo dórico, solo en medio del campo, tiene sus treinta y seis columnas, pero no tiene cella dentro, ni techo, y las columnas no están acanaladas: nunca se terminó. Quizá se interrumpió por la guerra contra Selinunte, en el 416 a.C.'],
   ['segesta_troya','Los descendientes de Troya','ELYMI','Los segestanos no son griegos: son élimos, y dicen descender de troyanos que huyeron con Eneas. Virgilio lo cuenta: Eneas dejó aquí a los viejos y a las mujeres cansados de navegar. Por eso Roma, que también se dice hija de Troya, los trata como parientes.'],
   ['segesta_engano','El engaño de Segesta','THVCYDIDES','Tucídides cuenta que en el 415 a.C. los segestanos pidieron ayuda a Atenas contra Selinunte, y prometieron pagar la guerra. Para convencer a los embajadores atenienses, reunieron toda la plata de las ciudades vecinas, la pasaron de casa en casa en cada banquete, y los atenienses creyeron que eran riquísimos.']],
  extra(I){temple({x:I.x+60,z:I.z+40,rot:0,W:23,L:58,nW:6,nL:14,colD:1.9,colH:9.4,name:'Templo de Segesta',noCella:true,noRoof:true});theatre({x:I.x-150,z:I.z-180,R0:8,R1:30,H:14,rot:Math.PI,name:'Teatro de Segesta',noPlays:true});}},
 // ---------------- Acaya
 corinthus:{npc:'faber_corinthius',label:'Corinto',roman:true,blobs:[[0,-300,170,140]],tx:0,tz:40,tr:110,site:[-80,-60,22],houses:44,spread:130,temple:{name:'Templo de Apolo (Corinto)',W:16,L:38,nW:6,nL:15},
  steles:[['corinto_mummio','Destruida y refundada','CORINTHVS','En el 146 a.C. el cónsul Mummio arrasó Corinto, mató a los hombres y vendió a las mujeres y los niños. Durante un siglo fue un campo de ruinas. Julio César la refundó en el 44 a.C. como colonia de libertos romanos, y hoy es la capital de la provincia de Acaya: un puerto en cada mar y mucho comercio.'],
   ['istmo','El istmo y el canal','ISTHMVS','Corinto controla el istmo que une el Peloponeso con el resto de Grecia. Los barcos se arrastran por tierra sobre una calzada de piedra, el diolkos. Hace trece años, Nerón empezó a excavar un canal, y dio él mismo el primer golpe de pico con una pala de oro. Las obras se abandonaron a su muerte.'],
   ['pablo_corinto','Un predicador de Tarso','PAVLVS','Hace unos treinta años vivió aquí un año y medio Pablo de Tarso, un judío que fabricaba tiendas de campaña y predicaba que Jesús de Nazaret, crucificado en Judea, había resucitado. Lo denunciaron ante el procónsul Galión, hermano de Séneca, que no quiso juzgarlo. Después escribió cartas a la comunidad de seguidores que dejó aquí.']],
  extra(I){r3Sea(I,'Corinto');const s=I.x,t=I.z-300;let top=0;for(let dx=-40;dx<=40;dx+=10)top=Math.max(top,terrainH(s+dx,t));romanTemple({x:s,z:t,gy:top-1,rot:0,W:10,L:16,pod:1.5,colD:0.6,colH:6,nW:4,name:'Templo de Afrodita (Acrocorinto)'});
   const f=findFree(I.x+60,I.z-20,2),g=grp(f[0],terrainH(f[0],f[1]),f[1],0);box(14,4,4,lam('#d8cdb2'),0,2,0,g);for(let k=0;k<6;k++)box(1.6,2.4,0.4,lam('#141110'),-5+k*2,1.2,2.1,g);addBox(f[0],f[1],14,4,0);
   r3Plaque(f[0],f[1]+5,'pirene','La fuente de Pirene','PEIRENE','El agua de Corinto sale de esta fuente con arcos, en el ágora. Dicen que aquí Belerofonte domó al caballo alado Pegaso mientras bebía.');}},
 athenae:{npc:'scholasticus',label:'Atenas',roman:true,blobs:[[0,-150,120,60],[-260,-260,180,30]],tx:60,tz:140,tr:110,site:[0,-150,40,62],houses:44,spread:130,temple:{name:'El Partenón',W:31,L:70,nW:8,nL:17,colD:1.9,colH:10.4},
  steles:[['atenas_universidad','La ciudad de los estudiantes','ATHENAE','Atenas ya no es una potencia, pero es la universidad del mundo romano: aquí vienen los jóvenes ricos de Roma a estudiar filosofía y retórica en la Academia de Platón, el Liceo de Aristóteles, el Jardín de Epicuro y la Stoa. Cicerón y Horacio estudiaron aquí. Los atenienses viven de su pasado y de los estudiantes.'],
   ['atenas_romanos','Atenas y Roma','ATHENAE','Sila saqueó Atenas en el 86 a.C. por apoyar a Mitrídates. Después, los romanos la colmaron de regalos: Augusto construyó un nuevo mercado con columnas, Agripa un gran teatro cubierto en el ágora, y en la Acrópolis, delante del Partenón, hay un templo redondo dedicado a Roma y a Augusto. Anacronismo señalado: el templo de Zeus Olímpico, a medio construir desde hace seis siglos, no lo terminará hasta Adriano, en el 131.'],
   ['pablo_atenas','Un discurso en el Areópago','AREOPAGVS','Hace treinta años, Pablo de Tarso habló ante el consejo del Areópago de un dios desconocido. Algunos se burlaron cuando habló de la resurrección de los muertos; otros dijeron: «Ya te oiremos otro día».']],
  extra(I){r3Sea(I,'el Pireo');const s=I.site;roundTemple({x:s.x+20,z:s.z+30,r:4,colD:0.45,colH:5,n:9,pod:1,gy:s.h,rot:0,name:'Templo de Roma y Augusto'});
   forumR(I.x+80,I.z+40,60,40,'Ágora romana de Atenas');r3Ruins(I.x-150,I.z+60,10,12,'#e8e2d0');
   r3Plaque(I.x-150,I.z+80,'olimpieion_atenas','El templo de Zeus Olímpico','OLYMPIEION','Columnas gigantes de un templo empezado por los tiranos hace seis siglos y nunca terminado. Sila se llevó a Roma algunas de sus columnas para el Capitolio.');}},
 delos:{npc:'phylax',label:'Delos',roman:true,blobs:[[60,-200,120,40]],tx:-40,tz:20,tr:60,houses:10,spread:60,site:[40,-40,22],temple:{name:'Templo de Apolo (Delos)'},
  steles:[['delos_desierta','Una isla casi vacía','DELOS','Hace poco más de un siglo, Delos era el mayor mercado de esclavos del Mediterráneo: Estrabón dice que podían venderse diez mil en un día. Pero en el 88 a.C. las tropas de Mitrídates la saquearon, y en el 69 a.C. los piratas la arrasaron otra vez. Hoy apenas vive gente: unos guardias atenienses y los sacerdotes.'],
   ['delos_leones','La terraza de los leones','LEONES','Junto al lago sagrado, una fila de leones de mármol de Naxos, de seis siglos de antigüedad, vigila el lugar donde nació Apolo. Antes eran más de nueve.']],
  extra(I){r3Sea(I,'Delos');for(let k=0;k<7;k++){const x=I.x+100+k*7,z=I.z-60,g=grp(x,terrainH(x,z),z,-Math.PI/2),m=M.marble;box(1,1.4,2.6,m,0,1,0,g);box(0.9,1.1,0.9,m,0,2.2,1.2,g);box(0.9,0.6,0.6,m,0,0.3,0,g);}
   const lk=new THREE.Mesh(new THREE.CircleGeometry(16,24),new THREE.MeshPhongMaterial({color:'#4f7a7a',shininess:60}));lk.rotation.x=-Math.PI/2;lk.position.set(I.x+120,terrainH(I.x+120,I.z-30)+0.2,I.z-30);scene.add(lk);
   r3Ruins(I.x-20,I.z+40,40,60,'#e8e2d0');}},
 // ---------------- Asia
 ephesus:{npc:'argentarius',label:'Éfeso',roman:true,blobs:[[-200,-260,200,50],[150,-280,160,40]],tx:0,tz:40,tr:110,site:[220,80,30],houses:50,spread:140,temple:{name:'El Artemisio',W:55,L:115,nW:8,nL:21,colD:1.8,colH:18},
  steles:[['artemisio','El templo de Ártemis','ARTEMISIVM','Una de las siete maravillas del mundo: el templo de Ártemis de Éfeso, con más de cien columnas de casi veinte metros. El primero lo quemó un tal Eróstrato, en el 356 a.C., solo para que su nombre se recordara; los efesios prohibieron pronunciarlo, y por eso todos lo sabemos. Se reconstruyó todavía más grande.'],
   ['efeso_teatro','El motín de los plateros','THEATRVM','Hace unos veinticinco años, un platero llamado Demetrio, que fabricaba templetes de plata de Ártemis para los peregrinos, reunió a sus colegas contra Pablo de Tarso, que decía que los dioses hechos a mano no son dioses. La multitud llenó el teatro y gritó dos horas: «¡Grande es la Ártemis de los efesios!».']],
  extra(I){r3Sea(I,'Éfeso');theatre({x:I.x-120,z:I.z-140,R0:12,R1:60,H:24,rot:0,name:'Teatro de Éfeso',noPlays:true});forumR(I.x+20,I.z+10,50,32,'Ágora de Éfeso');}},
 pergamum:{npc:'membranarius',label:'Pérgamo',roman:true,blobs:[[0,-160,220,110]],tx:0,tz:200,tr:90,site:[0,-160,30,110],houses:40,spread:120,
  steles:[['pergamo_altar','El gran altar','ARA PERGAMENA','En la acrópolis, los reyes atálidas construyeron un altar inmenso a Zeus, rodeado por un friso de mármol con la guerra entre los dioses y los gigantes: cuerpos que se retuercen, serpientes, alas y escudos. Anacronismo señalado: hoy este altar está en un museo de Berlín.'],
   ['pergamino','La biblioteca y el pergamino','PERGAMENA','Los reyes de Pérgamo quisieron tener una biblioteca como la de Alejandría. Cuenta Varrón que el rey de Egipto, celoso, prohibió vender papiro a Pérgamo; y aquí empezaron a escribir sobre pieles de animal preparadas: el pergamino. Antonio regaló doscientos mil libros de esta biblioteca a Cleopatra.'],
   ['asclepieion_perg','El santuario de Asclepio','ASCLEPIEION','Abajo, en la llanura, hay un santuario de Asclepio, el dios de la medicina, donde los enfermos duermen esperando un sueño que les diga la cura. Anacronismo señalado: Galeno, el médico más famoso de la Antigüedad, nacerá aquí dentro de unos cincuenta años.']],
  extra(I){const s=I.site;const g=grp(s.x,s.h,s.z+20,0),m=M.marble;box(36,5,34,m,0,2.5,0,g);box(20,2.5,14,m,0,4,-26,g);for(let k=0;k<14;k++)box(20,0.25,0.9,m,0,0.15+k*0.32,-18-k*0.9,g);for(let k=0;k<10;k++){const c=new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.4,4,10),m);c.position.set(-16+k*3.5,7,15);g.add(c);}addBox(s.x,s.z+20,36,34,0);
   theatre({x:s.x-90,z:s.z+40,R0:10,R1:50,H:36,rot:Math.PI/2,name:'Teatro de Pérgamo',noPlays:true});}},
 rhodus:{npc:'nauarchus',label:'Rodas',roman:true,blobs:[[-200,-200,200,40]],tx:-20,tz:0,tr:110,site:[-120,-140,22],houses:46,spread:130,temple:{name:'Templo de Helios (Rodas)'},
  steles:[['coloso','El Coloso caído','COLOSSVS','En la entrada del puerto había una estatua de bronce del dios Sol, Helios, de treinta y tres metros: el Coloso, una de las siete maravillas. Un terremoto lo derribó en el 226 a.C., solo cincuenta y seis años después de terminarlo. Plinio cuenta que, caído, sigue asombrando: pocos pueden abrazar su pulgar, y sus dedos son más grandes que muchas estatuas. Por dentro se ven las piedras que le servían de contrapeso.'],
   ['rodas_escuela','La escuela de Rodas','RHODVS','Rodas es famosa por sus marinos y por su escuela de retórica. Aquí vinieron a estudiar Cicerón y Julio César. El maestro Molón le enseñó a Cicerón a no gritar tanto en los discursos.']],
  extra(I){r3Sea(I,'Rodas');const x=I.x+I.R*0.25,z=I.z+60,bz=lam('#7a6a4a');for(const[dx,dz,l,r,a]of[[0,0,14,2.6,0.2],[12,6,9,1.6,0.6],[-10,-4,8,1.4,-0.4],[20,-8,6,2.2,1.2],[-18,10,5,1.1,0.9]]){const c=new THREE.Mesh(new THREE.CylinderGeometry(r,r*1.1,l,12,1,true),bz);c.material.side=THREE.DoubleSide;c.rotation.set(Math.PI/2,0,a);c.position.set(x+dx,terrainH(x+dx,z+dz)+r*0.7,z+dz);scene.add(c);addCirc(x+dx,z+dz,r);}
   egxObj(x,z-6,undefined,'r3:coloso','Trozos de bronce enormes','el Coloso caído',8);}},
 // ---------------- Siria, Judea, Chipre
 antiochia:{npc:'antiochenus',label:'Antioquía',roman:true,blobs:[[0,-330,320,110]],tx:0,tz:0,tr:120,site:[-80,-80,22],houses:56,spread:150,rtemple:{name:'Templo de Júpiter (Antioquía)'},
  steles:[['antioquia_calle','La gran calle de columnas','ANTIOCHIA','Antioquía, capital de la provincia de Siria, es la tercera ciudad del imperio después de Roma y Alejandría. La cruza una calle de más de tres kilómetros con pórticos a los dos lados, pavimentada con mármol por Herodes de Judea y por el emperador Tiberio. De noche, dicen, hay tantas lámparas que parece de día.'],
   ['dafne','Dafne','DAPHNE','A las afueras está Dafne, un bosque de laureles y cipreses con fuentes, consagrado a Apolo: aquí, dicen, la ninfa Dafne se convirtió en laurel para huir del dios. Los de Antioquía vienen a pasear, a beber y a divertirse; los moralistas dicen que demasiado.'],
   ['cristianos','Los primeros «cristianos»','CHRISTIANI','Fue aquí, cuenta el libro de los Hechos, donde a los seguidores de Jesús de Nazaret los llamaron por primera vez «cristianos». En Antioquía la comunidad mezclaba judíos y no judíos, y desde aquí salió Pablo de Tarso en sus viajes.']],
  extra(I){r3Sea(I,'Seleucia, el puerto de Antioquía');const z=I.z+60;for(let k=-14;k<=14;k++)for(const s of[-1,1]){const x=I.x+k*14,c=new THREE.Mesh(new THREE.CylinderGeometry(0.4,0.45,6,10),M.marble);c.position.set(x,terrainH(x,z+s*7)+3,z+s*7);c.castShadow=true;scene.add(c);addCirc(x,z+s*7,0.5);}
   const pts=[];for(let i=0;i<=30;i++){const t=i/30;pts.push([I.x-I.R*1.1+t*I.R*2,I.z+220+Math.sin(t*4)*20]);}addRiver(pts,22,{dep:2.5,name:'El Orontes'});}},
 hierosolyma:{npc:'veteranus',label:'Jerusalén',roman:true,blobs:[[0,-60,260,30],[-300,200,200,30]],tx:-300,tz:240,tr:50,houses:6,spread:40,
  tint:(x,z,h,c)=>{c.lerp(_c2.set('#c8b896'),0.35);},
  steles:[['jerusalen_70','Jerusalén, diez años después','HIEROSOLYMA','En el año 66, Judea se rebeló contra Roma. En el 70, después de un asedio de cinco meses, el actual emperador Tito tomó Jerusalén. El templo, uno de los edificios más grandes del mundo, ardió y fue derribado, y la ciudad fue arrasada. Murieron muchos miles de personas y otras tantas fueron vendidas como esclavos. Hoy aquí acampa la Legión X Fretensis.'],
   ['torres_herodes','Las tres torres','TVRRES','Tito solo dejó en pie un trozo de muralla y tres torres del palacio del rey Herodes: Fasael, Hípico y Mariamne, para que se viera qué ciudad tan fuerte habían vencido los romanos. Lo cuenta Flavio Josefo, un judío que fue general rebelde, se rindió y hoy vive en Roma, protegido por la familia de los Flavios.'],
   ['arco_tito','Lo que se llevaron a Roma','TITVS','Los tesoros del templo, entre ellos el gran candelabro de siete brazos de oro, desfilaron en Roma en el triunfo de Vespasiano y Tito, y hoy están en el templo de la Paz. Anacronismo cercano: dentro de unos años, el arco de Tito en el Foro mostrará esa procesión esculpida.']],
  extra(I){r3Tower(I.x-40,I.z-60,14,30,'#d8c8a0');r3Tower(I.x-10,I.z-62,10,24,'#d8c8a0');r3Tower(I.x+16,I.z-58,9,20,'#d8c8a0');box(60,10,4,lam('#d8c8a0'),I.x-14,terrainH(I.x-14,I.z-70)+5,I.z-70);addBox(I.x-14,I.z-70,60,4,0);
   r3Ruins(I.x+120,I.z-120,70,80,'#d8c8a0');r3Camp(I.x-160,I.z+20,90,70,'Campamento de la Legión X Fretensis');}},
 cyprus:{npc:'sacerdos_paphia',label:'Pafos',roman:true,blobs:[[-200,-250,220,60]],tx:20,tz:40,tr:100,site:[-120,-80,24],houses:40,spread:120,
  steles:[['venus_pafos','El santuario de la diosa de Pafos','PAPHIA','Afrodita, dicen los de aquí, salió de la espuma junto a esta costa, y su santuario es uno de los más antiguos del mundo. No la representan con una estatua: es una piedra cónica, oscura, que nadie sabe de dónde viene. Tácito cuenta que el joven Tito, camino de la guerra de Judea hace once años, vino a consultarla, y los sacerdotes le predijeron un gran futuro.'],
   ['cobre','La isla del cobre','CVPRVM','Chipre tiene las minas de cobre más famosas del Mediterráneo, explotadas desde hace dos mil años. Tanto que los romanos llaman al cobre «metal de Chipre»: aes Cyprium, y de ahí cuprum.']],
  extra(I){r3Sea(I,'Pafos');const s=I.site,g=grp(s.x,s.h,s.z,0);box(20,4,14,lam('#d8cdb2'),0,2,-6,g);for(let k=0;k<4;k++){const c=new THREE.Mesh(new THREE.CylinderGeometry(0.5,0.55,6,10),M.marble);c.position.set(-6+k*4,3,2);g.add(c);}box(16,1,3,M.marble,0,6.5,2,g);
   const st=new THREE.Mesh(new THREE.ConeGeometry(0.7,2.2,14),lam('#2a2624'));st.position.set(0,1.1,6);g.add(st);addBox(s.x,s.z-6,20,14,0);egxObj(s.x,s.z+8,s.h,'r3:piedra','Una piedra cónica y oscura','la diosa de Pafos',3);}},
 melita:{npc:'melitensis',label:'Melita',roman:true,blobs:[[-150,-150,160,30]],tx:-60,tz:-60,tr:80,houses:26,spread:80,
  steles:[['melita_pablo','Un naufragio','MELITA','Hace unos veinte años naufragó en esta costa un barco de trigo que llevaba prisioneros a Roma. Entre ellos iba Pablo de Tarso. Todos llegaron a nado o agarrados a tablas, y los habitantes, cuenta el libro de los Hechos, encendieron una hoguera para que se calentaran bajo la lluvia. Una víbora le mordió la mano a Pablo y no le pasó nada: los isleños pensaron que era un dios.'],
   ['melita_tejidos','Telas y miel','MELITA','Melita es famosa por sus telas finas: Cicerón cuenta que el gobernador Verres montó aquí un taller durante tres años para tejer vestidos para él. Su nombre, dicen, viene de meli, la miel, que es excelente. Y en lo alto hay templos de piedras gigantes, tan antiguos que los isleños dicen que los hicieron gigantes.']],
  extra(I){r3Sea(I,'Melita');const x=I.x+60,z=I.z-120,g=grp(x,terrainH(x,z),z,0),m=lam('#c9b88e');for(let k=0;k<14;k++){const a=k/14*Math.PI*1.6+0.6;box(rr(1.5,2.5),rr(2.5,4.5),1,m,Math.cos(a)*8,1.6,Math.sin(a)*6,g).rotation.y=-a;}addCirc(x,z,9);
   r3Plaque(x+11,z,'megalitos','Los templos de los gigantes','GIGANTES','Templos de bloques de piedra enormes, en forma de trébol, con altares y figuras de mujeres muy gordas. Hoy sabemos que tienen más de cinco mil años: son más antiguos que las pirámides de Egipto.');}},
 cyrene:{npc:'cyrenaeus',label:'Cirene',roman:true,blobs:[[0,-220,300,70]],tx:0,tz:-120,tr:90,site:[-120,-60,22,50],houses:36,spread:110,temple:{name:'Templo de Apolo (Cirene)'},
  steles:[['cirene_bato','La colonia de Tera','CYRENE','Cuenta Heródoto que el oráculo de Delfos mandó a los de la isla de Tera fundar una colonia en Libia, y que ellos, que no sabían ni dónde estaba, tardaron años en obedecer. Por fin, hacia el 631 a.C., un tal Bato fundó Cirene junto a una fuente de Apolo, en una meseta fértil y lluviosa sobre el mar.'],
   ['silfio','El silfio','SILPHIVM','Cirene se hizo rica con el silfio, una planta que solo crecía aquí, con la que se hacía un condimento y una medicina valiosísima: valía su peso en plata y aparece en las monedas de la ciudad. Plinio cuenta que en su tiempo ya no se encontraba, y que la última planta se le envió como regalo a Nerón. Hoy está extinguida.']],
  extra(I){r3Sea(I,'Apolonia, el puerto de Cirene');temple({x:I.x+100,z:I.z-40,rot:0,W:30,L:68,nW:8,nL:17,colD:2,colH:10,name:'Templo de Zeus (Cirene)'});caveMouth(I.x-160,I.z-90,0);r3Plaque(I.x-160,I.z-80,'fuente_apolo','La fuente de Apolo','CYRE','La fuente de agua por la que se fundó la ciudad. Le da su nombre: Kyre.');}},
 // ---------------- Lusitania
 olisipo:{npc:'olisiponensis',label:'Olisipo',roman:true,blobs:[[-150,-150,160,40]],tx:-60,tz:-80,tr:80,houses:36,spread:110,site:[-150,-150,20,40],
  steles:[['olisipo_tajo','La ciudad del Tajo','OLISIPO','Olisipo está en una colina sobre el estuario del Tajo, que aquí es casi un mar. Es municipio de ciudadanos romanos con el nombre de Felicitas Iulia. Junto al río hay grandes balsas donde se sala el pescado y se hace garum, que se envía en ánforas a todo el imperio.'],
   ['yeguas_viento','Las yeguas preñadas por el viento','FAVONIVS','Plinio y Varrón cuentan una historia muy extendida: aquí, junto a Olisipo, las yeguas se ponen de cara al viento del oeste y quedan preñadas por él, y sus potros son los más rápidos del mundo, aunque viven poco. Por supuesto, es una leyenda: probablemente nace de la fama de los caballos lusitanos.']],
  extra(I){r3Sea(I,'Olisipo');theatre({x:I.x-120,z:I.z-110,R0:8,R1:30,H:12,rot:Math.PI,name:'Teatro de Olisipo',noPlays:true});
   r3Plaque(I.x-100,I.z-120,'teatro_nero','Un teatro para Nerón','THEATRVM','Este teatro se reformó en el año 57 y se dedicó a Nerón: su inscripción todavía se conserva en Lisboa.');
   for(let k=0;k<6;k++){const x=I.x+100+(k%3)*10,z=I.z+60+Math.floor(k/3)*10;box(8,1,8,lam('#9a8a6a'),x,terrainH(x,z)+0.2,z);}egxObj(I.x+110,I.z+75,undefined,'r3:garum','Las balsas de salazón','huele muy fuerte',5);}},
 // ---------------- Britania
 londinium:{npc:'negotiator_brit',label:'Londinium',roman:true,blobs:[],tx:-40,tz:-60,tr:100,site:[-80,-120,22],houses:44,spread:120,rtemple:{name:'Templo de Londinium'},green:true,
  steles:[['londinium_boudica','La ciudad que ardió','LONDINIVM','Londinium la fundaron comerciantes hace poco más de treinta años, junto a un puente sobre el Támesis. En el año 60 la reina Boudica de los icenos se rebeló, harta de los abusos de los romanos, y la quemó con todos los que no habían huido: Tácito cuenta setenta mil muertos entre esta ciudad, Camuloduno y Verulamio. Hoy se reconstruye en piedra, con un foro nuevo.'],
   ['britania_clima','El cielo de Britania','BRITANNIA','Tácito escribe que en Britania el cielo está siempre nublado y la lluvia es frecuente, pero no hace un frío terrible. La tierra es buena para todo menos para el olivo y la vid. Se exporta trigo, ganado, hierro, plata, perros de caza y esclavos.']],
  extra(I){r3Sea(I,'Londinium');const pts=[];for(let i=0;i<=30;i++){const t=i/30;pts.push([I.x-I.R*1.1+t*I.R*2.2,I.z+120+Math.sin(t*3)*24]);}addRiver(pts,40,{dep:3,name:'El Támesis'});
   const bx=I.x-20,deck=4;stoneBridge(bx,I.z+90,bx,I.z+150,8,10,deck,lam('#7a5a3a'));for(let k=0;k<8;k++){const x=I.x-150+k*18,z=I.z+92;box(14,1,6,lam('#6a4a2a'),x,1.2,z);}forumR(I.x-20,I.z-40,50,32,'El nuevo foro de Londinium');}},
 caledonia:{npc:'miles_agricolae',label:'Campamento de Agrícola',roman:true,blobs:[[-300,-260,260,90],[300,-280,260,100],[0,-450,280,120]],tx:-300,tz:260,tr:40,houses:6,spread:40,green:true,
  tint:(x,z,h,c)=>{c.lerp(_c2.set('#4f6a3a'),0.4);if(h>60)c.lerp(_c2.set('#6a5a6a'),Math.min(0.5,(h-60)/40));},
  steles:[['agricola_80','El tercer verano de Agrícola','AGRICOLA','Estamos en el año 80, el tercer verano de campaña de Gneo Julio Agrícola, gobernador de Britania. Tácito, su yerno, cuenta que este año el ejército avanzó entre tormentas hasta el estuario del Taus, devastando a los pueblos que encontraba, y construyó fortines a su paso. Más allá están los caledonios, en sus montes y bosques.'],
   ['calgaco','«Crean un desierto…»','CALGACVS','Tácito pondrá en boca de Calgaco, un jefe caledonio, un discurso contra Roma antes de la batalla: «Robar, asesinar y saquear lo llaman, con falso nombre, imperio; y donde crean un desierto, lo llaman paz». Anacronismo señalado: esa batalla, la del monte Graupio, será dentro de tres o cuatro años, y Tácito la escribirá en el 98.']],
  extra(I){r3Camp(I.x,I.z,120,90,'Campamento de marcha','wood');for(let k=0;k<20;k++){const x=I.x-60+(k%10)*12,z=I.z+60+Math.floor(k/10)*10,g=grp(x,terrainH(x,z),z,0);const t=new THREE.Mesh(new THREE.ConeGeometry(2.4,2.4,4),lam('#8a6a48'));t.rotation.y=Math.PI/4;t.position.y=1.2;g.add(t);}}},
 // ---------------- Germania
 colonia:{npc:'vitrarius',label:'Colonia',roman:true,blobs:[],tx:-60,tz:0,tr:100,site:[-100,-80,22],houses:44,spread:120,rtemple:{name:'Templo del Capitolio (Colonia)'},green:true,
  steles:[['ccaa','La colonia de Agripina','COLONIA AGRIPPINENSIS','Aquí, en la orilla del Rin, vivían los ubios, un pueblo germano amigo de Roma. En el año 50, el emperador Claudio convirtió su ciudad en colonia romana a petición de su esposa Agripina, que había nacido aquí: Colonia Claudia Ara Agrippinensium. Al otro lado del río empieza la Germania libre.'],
   ['batavos','La rebelión de los bátavos','CIVILIS','Hace solo diez años, en el 69-70, mientras Roma se desangraba en guerra civil, el bátavo Julio Civil levantó a los germanos del Rin. Las legiones de aquí se rindieron, y Colonia tuvo que unirse a los rebeldes. Pero sus habitantes se negaron a matar a los romanos que vivían en la ciudad, y en cuanto pudieron volvieron con Roma.']],
  extra(I){const pts=[];for(let i=0;i<=30;i++){const t=i/30;pts.push([I.x+200+Math.sin(t*3)*20,I.z-I.R*1.1+t*I.R*2.2]);}addRiver(pts,60,{dep:3.5,name:'El Rin'});
   for(let k=0;k<4;k++){const g=grp(I.x+200,0.3,I.z-100+k*60,0);box(3,1.2,20,lam('#6a4a2a'),0,0.6,0,g);}}},
 mogontiacum:{npc:'legionarius',label:'Mogontiacum',roman:true,blobs:[[-200,-250,200,40]],tx:-200,tz:150,tr:70,houses:30,spread:90,green:true,
  steles:[['druso','El monumento de Druso','DRVSVS','Druso, el hermano del emperador Tiberio, conquistó la Germania hasta el Elba. Murió en el 9 a.C. al caerse del caballo, y sus soldados le levantaron aquí un gran monumento de piedra, donde cada año se celebran desfiles y juegos en su honor.'],
   ['columna_jupiter','La columna de Júpiter','IVPPITER','En tiempos de Nerón, los habitantes de las cabañas junto al campamento levantaron una columna de piedra de nueve metros cubierta de relieves de dioses, con una estatua de bronce de Júpiter arriba, por la salud del emperador. Se conservan sus trozos.']],
  extra(I){r3Camp(I.x+40,I.z-40,160,120,'Campamento de dos legiones');const x=I.x-150,z=I.z-120,y=terrainH(x,z),g=grp(x,y,z,0);box(12,6,12,lam('#b8ab88'),0,3,0,g);const c=new THREE.Mesh(new THREE.CylinderGeometry(4,5,14,16),lam('#b8ab88'));c.position.y=13;g.add(c);addBox(x,z,12,12,0);
   const cx=I.x-100,cz=I.z+100,cg=grp(cx,terrainH(cx,cz),cz,0);box(1.6,1.6,1.6,lam('#cdbf9f'),0,0.8,0,cg);const cc=new THREE.Mesh(new THREE.CylinderGeometry(0.5,0.55,9,12),lam('#cdbf9f'));cc.position.y=6;cg.add(cc);box(0.5,1.5,0.4,M.bronze||lam('#a8743a'),0,11.3,0,cg);addCirc(cx,cz,1);
   const pts=[];for(let i=0;i<=30;i++){const t=i/30;pts.push([I.x+260+Math.sin(t*3)*16,I.z-I.R*1.1+t*I.R*2.2]);}addRiver(pts,50,{dep:3.5,name:'El Rin'});}},
 // ---------------- Danubio y Dalmacia
 carnuntum:{npc:'miles_danubii',label:'Carnuntum',roman:true,blobs:[[-250,-260,200,40]],tx:-200,tz:150,tr:70,houses:30,spread:90,green:true,
  steles:[['carnuntum_campo','El campamento del Danubio','CARNVNTVM','Carnuntum, en la frontera de Panonia, es la base de la Legión XV Apollinaris, que acaba de volver de la guerra de Judea. Aquí la ruta del ámbar, que viene del norte, cruza el Danubio, la frontera del imperio. Al otro lado viven los cuados y los marcomanos.'],
   ['danubio','El Danubio','DANVVIVS','El Danubio, que los griegos llamaban Istro, es el río más largo que conocen los romanos después del Nilo. Nace en Germania y desemboca en el mar Negro. En invierno se hiela, y los bárbaros lo cruzan a caballo para saquear.']],
  extra(I){r3Camp(I.x+20,I.z-40,150,110,'Campamento de la Legión XV Apollinaris');const pts=[];for(let i=0;i<=30;i++){const t=i/30;pts.push([I.x-I.R*1.1+t*I.R*2.2,I.z-220+Math.sin(t*3)*20]);}addRiver(pts,70,{dep:3.5,name:'El Danubio'});}},
 salona:{npc:'dalmata',label:'Salona',roman:true,blobs:[[0,-300,300,80],[-300,-100,160,40]],tx:0,tz:0,tr:100,site:[-80,-60,22],houses:44,spread:120,rtemple:{name:'Templo de Salona'},
  steles:[['salona_capital','La capital de Dalmacia','SALONA','Salona, en una bahía protegida por islas, es la capital de la provincia de Dalmacia. Los dálmatas e ilirios se rebelaron con fuerza contra Augusto: la gran revuelta del 6 al 9 d.C. tuvo a Tiberio luchando tres años. Hoy la costa es tranquila y rica; el interior, montañoso, da plata y hierro.'],
   ['diocleciano','El palacio que vendrá','SPALATVM','Anacronismo señalado: dentro de unos doscientos años nacerá cerca de aquí Diocleciano, que será emperador y construirá, a pocos kilómetros, un enorme palacio fortificado para su retiro. Alrededor de ese palacio crecerá la ciudad de Split.']],
  extra(I){r3Sea(I,'Salona');amphi(I.x+130,I.z-60,0,62,50,12,'Anfiteatro de Salona');forumR(I.x-20,I.z+10,44,28,'Foro de Salona');}},
 // ---------------- África
 caesarea_m:{npc:'mauretanus',label:'Cesarea de Mauritania',roman:true,blobs:[[0,-300,320,60]],tx:0,tz:-40,tr:110,site:[-80,-120,22],houses:44,spread:130,temple:{name:'Templo de Augusto (Cesarea)'},
  steles:[['juba_selene','El rey sabio y la hija de Cleopatra','IVBA','Cesarea fue la capital de Juba II, un rey africano educado en Roma, y de su esposa Cleopatra Selene, la hija de Marco Antonio y de Cleopatra de Egipto. Juba escribió libros de geografía, historia y teatro que todavía lee Plinio. Su hijo Ptolomeo fue el último rey: Calígula lo mandó matar en el 40, y Mauritania se hizo provincia romana.'],
   ['citrus','Las mesas de cidro','CITRVS','De los bosques de Mauritania sale la madera de cidro (una especie de tuya) con vetas como plumas de pavo real. Plinio cuenta que una mesa de una sola pieza puede costar tanto como una finca: Cicerón pagó medio millón de sestercios por una. A las mujeres que les reprochaban sus perlas, sus maridos les reprochaban sus mesas.']],
  extra(I){r3Sea(I,'Cesarea');theatre({x:I.x+120,z:I.z-140,R0:8,R1:34,H:14,rot:Math.PI,name:'Teatro de Cesarea',noPlays:true});r3Lighthouse(I.x+I.R*0.3,I.z+I.R*0.3,24);}},
 cirta:{npc:'numida',label:'Cirta',roman:true,blobs:[[-150,-200,200,50]],tx:-150,tz:-200,tr:90,site:[-120,-160,22,50],houses:36,spread:100,rtemple:{name:'Templo de Cirta'},
  tint:(x,z,h,c)=>{c.lerp(_c2.set('#c8a870'),0.3);},
  steles:[['masinisa','La ciudad de Masinisa','CIRTA','Cirta, sobre una roca rodeada por un barranco, fue la capital de los reyes de Numidia. Masinisa, aliado de Escipión contra Aníbal, la hizo rica: a los noventa años todavía montaba a caballo sin silla. Su nieto Yugurta sobornó a medio senado de Roma, hasta que lo venció Mario.'],
   ['salustio','Salustio en África','SALLVSTIVS','El historiador Salustio, que escribió la Guerra de Yugurta, fue gobernador de esta tierra para César, y volvió a Roma tan rico que compró los famosos jardines de Salustio. Su libro empieza diciendo que todos deben ganarse la gloria con su talento.']],
  extra(I){for(let k=0;k<12;k++){const x=I.x+100+rr(-60,60),z=I.z+80+rr(-60,60);box(14,0.3,10,lam('#d8bf6a'),x,terrainH(x,z)+0.1,z);}egxObj(I.x+100,I.z+80,undefined,'r3:trigo','Campos de trigo','el trigo de Numidia',8);}}
});
